import { Link,useParams } from 'react-router-dom';import { useEffect,useState } from 'react';import { LocalOrder,formatMoney } from '../../lib/api';
export default function Confirmacao(){const {numero}=useParams();const [order,setOrder]=useState<LocalOrder|null>(null);useEffect(()=>{setOrder(JSON.parse(localStorage.getItem('gp_last_order')||'null'))},[]);function imprimir(){window.print()}return <section className="containerx py-20 fade"><div className="card p-10 max-w-3xl mx-auto"><div className="text-center"><span className="badge bg-success/10 text-success">Pedido enviado</span><h1 className="font-display text-4xl text-primary mt-4">Recebemos sua solicitação</h1><p className="mt-4 text-gray-600">Número do pedido: <b>{numero}</b></p><p className="mt-2 text-gray-600">A confirmação do pagamento, produção e entrega será feita pelo WhatsApp.</p></div>{order&&<div className="mt-8 border rounded-3xl p-6 bg-gray-50"><div className="flex items-center gap-4"><img src="/assets/logo-icon.png" className="w-16 h-16"/><div><h2 className="font-display text-2xl text-primary">Recibo do pedido</h2><p className="text-sm text-gray-500">Gráfica W Criações · Pedido {order.numero}</p></div></div><div className="grid md:grid-cols-2 gap-4 mt-6 text-sm"><p><b>Cliente:</b> {order.cliente.nome}</p><p><b>Telefone:</b> {order.cliente.telefone}</p><p className="md:col-span-2"><b>Endereço:</b> {order.cliente.endereco}</p></div><div className="mt-5">{order.items.map(i=><p className="flex justify-between border-t py-2" key={i.id}><span>{i.quantidade}x {i.nome}</span><b>{formatMoney(i.preco_unitario*i.quantidade)}</b></p>)}</div><p className="flex justify-between border-t pt-3 text-xl"><span>Total parcial</span><b>{formatMoney(order.total)}</b></p></div>}<div className="flex flex-wrap gap-3 justify-center mt-8 no-print"><button className="btn btn-primary" onClick={imprimir}>Emitir recibo</button><Link className="btn btn-dark" to="/acompanhar">Acompanhar pedido</Link><Link className="btn btn-outline" to="/catalogo">Voltar ao Catálogo</Link></div></div></section>}
